// Fixture dependency for the CLI round-trip test. readData() is the "legitimate" use that
// observe should record into the policy; readOther() is the "new, unexpected" use that a
// policy generated from main.js must deny in enforce mode.
const fs = require("fs");
const path = require("path");

exports.readData = () => fs.readFileSync(path.join(__dirname, "data.txt"), "utf8");
exports.readOther = () => fs.readFileSync(path.join(__dirname, "other.txt"), "utf8");

// Native-addon load (#49). `build/Release/<name>.node` is node-gyp's canonical output path,
// so this is the shape a real native package has. The file is a placeholder — see it — and
// the gate decides before dlopen reaches it either way.
exports.loadAddon = () => require(path.join(__dirname, "build", "Release", "trace-dep.node"));

// --- net host globs (#83) round-trip ---------------------------------------------------
//
// The helper resolves with a STRING the test can assert on: "CapabilityError" means capwall's
// guard denied the connect before any socket opened, anything else means it let the call
// through. It does not depend on the connection actually succeeding, which is what keeps the
// test deterministic — capwall decides before the OS is involved.

/** Connect to a TCP host:port. The host is not expected to resolve. */
exports.connectHost = (host, port) =>
  new Promise((resolve) => {
    const net = require("net");
    let sock;
    try {
      sock = net.connect({ host, port });
    } catch (err) {
      return resolve(err.name);
    }
    const done = () => {
      sock.destroy();
      resolve("allowed-through");
    };
    sock.on("connect", done);
    sock.on("error", done);
  });
